#include "EngineHost.h"
#include "Weather.h"
#include "RuntimeUI.h"
#include "ScreenshotWriter.h"
#include <glm/gtc/matrix_transform.hpp>
#include <cstdio>
#include <filesystem>
#include <algorithm>
using Pixels=std::vector<unsigned char>;
int main(){const int w=640,h=360;EngineHost host;std::string error;if(!host.Init("Judas issues 18 and 19 investigation",w,h,false,error)){std::printf("INIT_FAIL %s\n",error.c_str());return 2;}auto& window=host.GetWindow();auto& r=host.GetRenderer();
 WeatherSettings settings;WeatherPreset("sunny",settings.profile);settings.profile.cloudCoverage=0;settings.profile.rain=settings.profile.snow=settings.profile.fog=settings.profile.tornado=0;WeatherRuntime runtime(settings);auto weather=runtime.Sample({0,2,0});weather.active=true;weather.weight=1;
 auto frame=[&](const char* name,bool enabled,glm::vec3 background,glm::vec3 sun,glm::vec3 colour,glm::vec3 ambient){r.SetSceneAppearance(false,1,{},1,{1,0,0,0},false,background);r.BeginFrame(w,h);r.SetCamera(glm::lookAt(glm::vec3(0,2,0),glm::vec3(0,2,-1),glm::vec3(0,1,0)),glm::perspective(glm::radians(65.f),float(w)/h,.1f,100000.f));r.SetLighting(sun,colour,ambient);r.ClearWeather();if(enabled)r.SetWeather(weather,{0,2,0},1);r.DrawWeather(false);r.EndFrame();Pixels p;r.CaptureFrame(w,h,p);double sum[3]={};for(size_t i=0;i<p.size();++i)sum[i%3]+=p[i];std::printf("SKY %s enabled=%d mean_rgb=%.6f,%.6f,%.6f gl_error=%u\n",name,enabled,sum[0]/(w*h),sum[1]/(w*h),sum[2]/(w*h),glGetError());WriteRgbPng(std::string("/tmp/judas-issues18-19-flight-review/")+name+".png",w,h,p);return p;};
 auto day=frame("day-weather",true,{.52,.72,.9},{.35,.8,.45},{1,.96,.88},{.3,.34,.4});auto night=frame("night-weather",true,{.012,.018,.04},{-.3,.6,.2},.12f*glm::vec3(.55,.65,.95),{.035,.045,.08});auto off=frame("night-no-weather",false,{.012,.018,.04},{-.3,.6,.2},.12f*glm::vec3(.55,.65,.95),{.035,.045,.08});frame("sun-below-horizon",true,{.012,.018,.04},{0,-1,0},{0,0,0},{0,0,0});
 window.SetMouseCaptured(false);window.PollEvents();window.Input().Reset();auto button=[&](Uint32 type){SDL_Event e{};e.type=type;e.button.type=type;e.button.button=SDL_BUTTON_LEFT;e.button.x=320;e.button.y=180;SDL_PushEvent(&e);};button(SDL_MOUSEBUTTONDOWN);button(SDL_MOUSEBUTTONUP);window.PollEvents();auto action=window.Input().Action("ui_click");window.Input().BeginFixedStep();auto fixed=window.Input().FixedAction("ui_click");std::printf("SDL_SAME_POLL held=%d pressed=%d released=%d fixed_pressed=%d fixed_released=%d pointer_down=%d\n",action.held,action.pressed,action.released,fixed.pressed,fixed.released,window.Input().Pointer().down);
 UIDocument doc;const std::string path="/tmp/judas-issues18-19-flight-review/projects/flight_sim/Assets/ui/hangar.judasui";if(!LoadUIDocument(path,doc,error)){std::printf("UI_LOAD_FAIL %s\n",error.c_str());return 3;}doc.visible=true;doc.modal=true;RuntimeUI ui;auto handle=ui.Add(doc,"flight-hangar",1,error);ui.Layout(w,h);auto* layout=ui.LayoutOf(handle,"fly");if(!layout){std::puts("FLY_LAYOUT_MISSING");return 4;}auto point=layout->rect.position+layout->rect.size*.5f;
 auto click=[&](const char* name,bool shortClick){window.Input().Reset();window.Input().BeginFrame();window.Input().SetPhysical("mouse:Left",1);if(shortClick)window.Input().SetPhysical("mouse:Left",0);ui.Input(window.Input(),point,true,w,h);if(!shortClick){window.Input().BeginFrame();window.Input().SetPhysical("mouse:Left",0);ui.Input(window.Input(),point,true,w,h);}auto events=ui.TakeEvents();unsigned count=0;for(auto& e:events)count+=e.element=="fly"&&e.type=="click";std::printf("ACTUAL_FLIGHT_UI %s click_events=%u\n",name,count);};click("same-frame",true);click("two-frame-control",false);
 window.Input().Reset();window.SetTestInputMode(true);window.BeginTestFrame();window.SetTestPointer(160,90);window.Input().SetPhysical("mouse:Left",1);auto pointer=window.Input().Pointer();int x,y;window.GetMousePosition(x,y);std::printf("HARNESS pointer_legacy=%d,%d public_pointer=%.3f,%.3f down=%d action_held=%d\n",x,y,pointer.x,pointer.y,pointer.down,window.Input().Action("ui_click").held);
 return 0;}
